import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Button,
  Alert,
  CircularProgress,
  List,
  ListItem,
  Chip,
  IconButton,
  Tooltip,
  Avatar,
  LinearProgress,
  Divider,
  Paper
} from '@mui/material';
import {
  PlayArrow as StartIcon,
  People as PeopleIcon,
  CheckCircle as CheckIcon,
  Cancel as CancelIcon,
  Refresh as ResetIcon,
  Visibility as ViewIcon,
  Timer as TimerIcon,
  School as SchoolIcon,
  Stop as StopIcon,
  Analytics as AnalyticsIcon
} from '@mui/icons-material';
import { QuizResultsModal } from './QuizResultsModal';
import { QuizStatisticsModal } from './QuizStatisticsModal';

// Grade conversion function for German system
const percentageToGrade = (percentage: number): number => {
  if (percentage >= 95.0) return 1.0;
  if (percentage >= 90.0) return 1.3;
  if (percentage >= 85.0) return 1.7;
  if (percentage >= 80.0) return 2.0;
  if (percentage >= 75.0) return 2.3;
  if (percentage >= 70.0) return 2.7;
  if (percentage >= 65.0) return 3.0;
  if (percentage >= 60.0) return 3.3;
  if (percentage >= 55.0) return 3.7;
  if (percentage >= 50.0) return 4.0;
  if (percentage >= 45.0) return 4.3;
  if (percentage >= 40.0) return 4.7;
  if (percentage >= 35.0) return 5.0;
  if (percentage >= 20.0) return 5.3;
  return 6.0; // unter 20.0%
};

// Grade conversion function for MSS system
const percentageToMSSPoints = (percentage: number): number => {
  if (percentage >= 95.0) return 15;
  if (percentage >= 90.0) return 14;
  if (percentage >= 85.0) return 13;
  if (percentage >= 80.0) return 12;
  if (percentage >= 75.0) return 11;
  if (percentage >= 70.0) return 10;
  if (percentage >= 65.0) return 9;
  if (percentage >= 60.0) return 8;
  if (percentage >= 55.0) return 7;
  if (percentage >= 50.0) return 6;
  if (percentage >= 45.0) return 5;
  if (percentage >= 40.0) return 4;
  if (percentage >= 35.0) return 3;
  if (percentage >= 20.0) return 2;
  if (percentage >= 10.0) return 1;
  return 0; // unter 10.0%
};

interface QuizSessionManagerProps {
  quizId: string;
  teacherId: string;
}

interface QuizSession {
  id: string;
  isActive: boolean;
  startedAt: string;
  endedAt?: string;
  participations?: Array<{
    id: string;
    student: {
      id: string;
      name: string;
    };
    score?: number;
    maxScore?: number;
    completedAt?: string;
  }>;
}

export const QuizSessionManager: React.FC<QuizSessionManagerProps> = ({
  quizId,
  teacherId
}) => {
  const [quiz, setQuiz] = useState<any>(null);
  const [sessions, setSessions] = useState<QuizSession[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedSession, setSelectedSession] = useState<QuizSession | null>(null);
  const [showResultsModal, setShowResultsModal] = useState(false);
  const [showStatisticsModal, setShowStatisticsModal] = useState(false);
  const [selectedParticipationId, setSelectedParticipationId] = useState<string | null>(null);
  const [selectedStudentName, setSelectedStudentName] = useState<string | null>(null);
  const [gradingSystem, setGradingSystem] = useState<string>('GERMAN'); // Default to German system

  // Function to determine grading system
  const getGradingSystem = (quizData: any): string => {
    console.log('🔍 getGradingSystem called with:', {
      gradeCategory: quizData?.gradeCategory,
      teacherGroups: quizData?.teacher?.teacherGroups?.length || 0
    });
    
    // Try to get grading system from quiz's teacher's teacherGroups
    if (quizData?.teacher?.teacherGroups?.length > 0) {
      // First, try to find a group that matches the quiz's gradeCategory AND has MSS system
      for (const group of quizData.teacher.teacherGroups) {
        console.log('🔍 Checking group:', group.name);
        if (group.gradingSchemas && group.gradingSchemas.length > 0) {
          // Check if any schema has a category that matches the quiz's gradeCategory
          for (const schema of group.gradingSchemas) {
            console.log('🔍 Checking schema:', schema.name, 'gradingSystem:', schema.gradingSystem);
            if (schema.structure && schema.structure.includes(quizData.gradeCategory)) {
              console.log('✅ Found matching schema:', schema.name, 'with gradingSystem:', schema.gradingSystem);
              
              // Prioritize MSS system if found
              if (schema.gradingSystem === 'MSS') {
                console.log('🎯 Prioritizing MSS system for:', group.name);
                return 'MSS';
              }
            }
          }
        }
      }
      
      // If no MSS system found, fall back to any matching schema
      for (const group of quizData.teacher.teacherGroups) {
        if (group.gradingSchemas && group.gradingSchemas.length > 0) {
          for (const schema of group.gradingSchemas) {
            if (schema.structure && schema.structure.includes(quizData.gradeCategory)) {
              console.log('🔄 Fallback to schema:', schema.name, 'with gradingSystem:', schema.gradingSystem);
              return schema.gradingSystem || 'GERMAN';
            }
          }
        }
      }
    }
    console.log('⚠️ No matching schema found, using default GERMAN');
    return 'GERMAN'; // Default fallback
  };

  useEffect(() => {
    fetchQuizData();
  }, [quizId]);

  useEffect(() => {
    if (!selectedSession) {
      // Wenn keine aktive Session, lade die letzten Ergebnisse
      fetchLastSessionResults();
    }
  }, [selectedSession]);

  useEffect(() => {
    if (selectedSession && selectedSession.isActive) {
      const interval = setInterval(fetchActiveSession, 5000); // Alle 5 Sekunden aktualisieren
      return () => clearInterval(interval);
    }
  }, [selectedSession]);

  // Debug logging for grading system
  useEffect(() => {
    if (gradingSystem) {
      console.log('🎯 Current grading system:', gradingSystem);
    }
  }, [gradingSystem]);

  const fetchQuizData = async () => {
    try {
      const response = await fetch(`/api/quizzes/${quizId}`);
      if (response.ok) {
        const quizData = await response.json();
        setQuiz(quizData);
        const detectedGradingSystem = getGradingSystem(quizData);
        console.log('🎯 Setting grading system to:', detectedGradingSystem);
        setGradingSystem(detectedGradingSystem); // Set grading system on quiz load
        await fetchActiveSession();
      } else {
        setError('Quiz konnte nicht geladen werden');
      }
    } catch (err) {
      setError('Fehler beim Laden des Quiz');
    } finally {
      setLoading(false);
    }
  };

  const fetchActiveSession = async () => {
    try {
      const response = await fetch(`/api/quiz-sessions/${quizId}/active`);
      if (response.ok) {
        const sessionData = await response.json();
        setSelectedSession(sessionData);
      }
    } catch (err) {
      console.error('Error fetching active session:', err);
    }
  };

  const fetchLastSessionResults = async () => {
    try {
      const response = await fetch(`/api/quiz-sessions/${quizId}/sessions`);
      if (response.ok) {
        const sessionsData = await response.json();
        // Get the most recent session
        if (sessionsData.length > 0) {
          const lastSession = sessionsData[sessionsData.length - 1];
          setSelectedSession(lastSession);
        }
      }
    } catch (err) {
      console.error('Error fetching last session:', err);
    }
  };

  const handleStartSession = async () => {
    setLoading(true);
    try {
      const response = await fetch(`/api/quiz-sessions/${quizId}/start`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ teacherId }),
      });

      if (response.ok) {
        const sessionData = await response.json();
        setSelectedSession(sessionData);
        setError(null);
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Session konnte nicht gestartet werden');
      }
    } catch (err) {
      setError('Fehler beim Starten der Session');
    } finally {
      setLoading(false);
    }
  };

  const handleResetParticipation = async (participationId: string, studentName: string) => {
    if (!window.confirm(`Teilnahme von ${studentName} wirklich zurücksetzen?`)) {
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(`/api/quiz-participations/${participationId}/reset`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ teacherId }),
      });

      if (response.ok) {
        // Aktualisiere die Session-Daten
        await fetchActiveSession();
        setError(null);
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Fehler beim Zurücksetzen der Teilnahme');
      }
    } catch (err) {
      setError('Fehler beim Zurücksetzen der Teilnahme');
    } finally {
      setLoading(false);
    }
  };

  const handleViewResults = async (participationId: string, studentName: string) => {
    setLoading(true);
    try {
      const response = await fetch(`/api/quiz-participations/${participationId}/results/teacher`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ teacherId }),
      });

      if (response.ok) {
        const results = await response.json();
        setSelectedParticipationId(participationId);
        setSelectedStudentName(studentName);
        setShowResultsModal(true);
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Auswertung konnte nicht geladen werden');
      }
    } catch (err) {
      setError('Fehler beim Laden der Auswertung');
    } finally {
      setLoading(false);
    }
  };

  const handleViewStatistics = async (sessionId: string) => {
    setLoading(true);
    try {
      const response = await fetch(`/api/quiz-participations/${sessionId}/statistics`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ teacherId }),
      });

      if (response.ok) {
        const stats = await response.json();
        setSelectedParticipationId(sessionId);
        setSelectedStudentName(null); // No specific student for statistics
        setShowStatisticsModal(true);
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Statistiken konnten nicht geladen werden');
      }
    } catch (err) {
      setError('Fehler beim Laden der Statistiken');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="200px">
        <Box sx={{ textAlign: 'center' }}>
          <CircularProgress size={40} sx={{ mb: 1 }} />
          <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.8rem' }}>
            Lade Quiz-Daten...
          </Typography>
        </Box>
      </Box>
    );
  }

  if (error) {
    return (
      <Alert severity="error" sx={{ mb: 2, borderRadius: 1, fontSize: '0.8rem' }}>
        {error}
      </Alert>
    );
  }

  const completedParticipations = selectedSession?.participations?.filter(p => p.completedAt) || [];
  const activeParticipations = selectedSession?.participations?.filter(p => !p.completedAt) || [];
  const totalParticipations = selectedSession?.participations?.length || 0;
  const completionRate = totalParticipations > 0 ? Math.round((completedParticipations.length / totalParticipations) * 100) : 0;

  return (
    <Box sx={{ maxWidth: 600, mx: 'auto' }}>
      {/* Quiz Header */}
      <Card sx={{ 
        mb: 2, 
        background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
        color: 'white',
        borderRadius: 2,
        boxShadow: '0 4px 16px rgba(0,0,0,0.1)'
      }}>
        <CardContent sx={{ p: 2 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 1.5 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
              <Avatar sx={{ 
                bgcolor: 'rgba(255,255,255,0.2)',
                width: 40,
                height: 40
              }}>
                <SchoolIcon />
              </Avatar>
    <Box>
                <Typography variant="h6" sx={{ fontWeight: 700, fontSize: '1rem' }}>
            {quiz?.title}
          </Typography>
                <Typography variant="body2" sx={{ opacity: 0.9, fontSize: '0.8rem' }}>
            {quiz?.description}
          </Typography>
              </Box>
            </Box>
            
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Chip 
                icon={<PeopleIcon />}
                label={`${quiz?.questions?.length || 0} Fragen`}
                size="small"
                sx={{ 
                  bgcolor: 'rgba(255,255,255,0.2)', 
                  color: 'white',
                  fontWeight: 600,
                  fontSize: '0.65rem',
                  height: 24
                }}
              />
              <Chip 
                icon={<TimerIcon />}
                label={`${quiz?.timeLimit || 0} Min.`}
                size="small"
                sx={{ 
                  bgcolor: 'rgba(255,255,255,0.2)', 
                  color: 'white',
                  fontWeight: 600,
                  fontSize: '0.65rem',
                  height: 24
                }}
              />
            </Box>
          </Box>
        </CardContent>
      </Card>

      {!selectedSession ? (
        /* Start Session Card */
        <Card sx={{ 
          background: 'rgba(255,255,255,0.95)',
          borderRadius: 2,
          boxShadow: '0 4px 16px rgba(0,0,0,0.1)',
          border: '1px solid rgba(255,255,255,0.2)'
        }}>
          <CardContent sx={{ p: 2.5, textAlign: 'center' }}>
            <Avatar sx={{ 
              bgcolor: 'primary.main',
              width: 56,
              height: 56,
              mx: 'auto',
              mb: 2
            }}>
              <StartIcon sx={{ fontSize: 28 }} />
            </Avatar>
            
            <Typography variant="h6" sx={{ mb: 1, fontWeight: 600, fontSize: '1rem' }}>
              Quiz Session starten
            </Typography>
            
            <Typography variant="body2" color="text.secondary" sx={{ mb: 2.5, fontSize: '0.8rem' }}>
              Starten Sie eine neue Quiz-Session für Ihre Schüler
            </Typography>
            
              <Button
                variant="contained"
              size="medium"
                startIcon={<StartIcon />}
                onClick={handleStartSession}
                disabled={loading}
              sx={{
                minWidth: 140,
                height: 40,
                py: 1,
                px: 2.5,
                fontSize: '0.85rem',
                fontWeight: 600,
                borderRadius: 2,
                background: 'linear-gradient(135deg, #4caf50 0%, #45a049 100%)',
                boxShadow: '0 4px 12px rgba(76, 175, 80, 0.3)',
                transition: 'all 0.2s ease',
                '&:hover': {
                  background: 'linear-gradient(135deg, #45a049 0%, #3d8b40 100%)',
                  boxShadow: '0 6px 16px rgba(76, 175, 80, 0.4)',
                  transform: 'translateY(-1px)'
                }
              }}
              >
                Session starten
              </Button>
          </CardContent>
        </Card>
      ) : (
        /* Active Session Card */
        <Card sx={{ 
          background: 'rgba(255,255,255,0.95)',
          borderRadius: 2,
          boxShadow: '0 4px 16px rgba(0,0,0,0.1)',
          border: '1px solid rgba(255,255,255,0.2)'
        }}>
          <CardContent sx={{ p: 2 }}>
            {/* Session Header */}
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
                <Avatar sx={{ 
                  bgcolor: selectedSession.isActive ? 'success.main' : 'grey.500',
                  width: 36,
                  height: 36
                }}>
                  {selectedSession.isActive ? <StartIcon /> : <StopIcon />}
                </Avatar>
                <Box>
                  <Typography variant="h6" sx={{ fontWeight: 600, fontSize: '0.9rem' }}>
                    {selectedSession.isActive ? 'Aktive Session' : 'Letzte Session'}
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.7rem' }}>
                    {selectedSession.isActive ? 'Gestartet' : 'Beendet'}: {new Date(selectedSession.isActive ? selectedSession.startedAt : (selectedSession.endedAt || selectedSession.startedAt)).toLocaleString('de-DE')}
              </Typography>
                </Box>
              </Box>
              
              {/* Statistics Button */}
              {completedParticipations.length > 0 && (
                <Tooltip title="Quiz-Statistik anzeigen">
                  <Button
                    variant="outlined"
                    size="small"
                    startIcon={<AnalyticsIcon />}
                    onClick={() => handleViewStatistics(selectedSession.id)}
                    disabled={loading}
                    sx={{
                      minWidth: 120,
                      height: 32,
                      fontSize: '0.7rem',
                      fontWeight: 600,
                      borderRadius: 1.5,
                      borderColor: 'primary.main',
                      color: 'primary.main',
                      '&:hover': {
                        borderColor: 'primary.dark',
                        bgcolor: 'primary.main',
                        color: 'white'
                      }
                    }}
                  >
                    Statistik
                  </Button>
                </Tooltip>
              )}
            </Box>
            
            {/* Participation Stats */}
            <Box sx={{ mb: 2 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mb: 1.5 }}>
                <PeopleIcon color="primary" sx={{ fontSize: 20 }} />
                <Typography variant="subtitle2" sx={{ fontWeight: 600, fontSize: '0.8rem' }}>
                  Teilnehmer: {totalParticipations}
            </Typography>
              </Box>
              
              <Box sx={{ mb: 1.5 }}>
                <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
                  <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                    Fortschritt
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 600, fontSize: '0.65rem' }}>
                    {completionRate}%
              </Typography>
                </Box>
                <LinearProgress 
                  variant="determinate" 
                  value={completionRate} 
                  sx={{ 
                    height: 6, 
                    borderRadius: 3,
                    backgroundColor: 'rgba(0,0,0,0.1)',
                    '& .MuiLinearProgress-bar': {
                      background: 'linear-gradient(90deg, #4caf50 0%, #45a049 100%)',
                      borderRadius: 3
                    }
                  }} 
                />
              </Box>
              
              <Box sx={{ display: 'flex', gap: 1.5, flexWrap: 'wrap' }}>
                <Chip 
                  icon={<CheckIcon />}
                  label={`${completedParticipations.length} Abgeschlossen`}
                  color="success"
                  variant="outlined"
                  size="small"
                  sx={{ fontWeight: 600, fontSize: '0.65rem', height: 20 }}
                />
                <Chip 
                  icon={<TimerIcon />}
                  label={`${activeParticipations.length} Aktiv`}
                  color="warning"
                  variant="outlined"
                  size="small"
                  sx={{ fontWeight: 600, fontSize: '0.65rem', height: 20 }}
                />
              </Box>
            </Box>

            <Divider sx={{ my: 2 }} />

            {/* Participants List */}
            {selectedSession.participations && selectedSession.participations.length > 0 && (
              <Box>
                <Typography variant="subtitle2" sx={{ mb: 1.5, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 0.5, fontSize: '0.75rem' }}>
                  <PeopleIcon color="primary" sx={{ fontSize: 16 }} />
                  Teilnehmer
                </Typography>
                
                <List sx={{ p: 0 }}>
                  {selectedSession.participations.map((participation) => {
                    const isCompleted = !!participation.completedAt;
                    const percentage = participation.maxScore && participation.score 
                      ? Math.round((participation.score / participation.maxScore) * 100) 
                      : 0;
                    
                    return (
                      <Paper 
                        key={participation.id} 
                        sx={{ 
                          mb: 1, 
                          borderRadius: 1,
                          background: isCompleted 
                            ? 'linear-gradient(135deg, #e8f5e8 0%, #c8e6c9 100%)'
                            : 'linear-gradient(135deg, #fff3e0 0%, #ffe0b2 100%)',
                          border: `1px solid ${isCompleted ? '#4caf50' : '#ff9800'}`,
                          transition: 'all 0.2s ease',
                          '&:hover': {
                            transform: 'translateY(-1px)',
                            boxShadow: '0 3px 8px rgba(0,0,0,0.1)'
                          }
                        }}
                      >
                        <ListItem sx={{ p: 1.5 }}>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, flex: 1 }}>
                            <Avatar sx={{ 
                              bgcolor: isCompleted ? '#4caf50' : '#ff9800',
                              width: 28,
                              height: 28
                            }}>
                              {participation.student.name.charAt(0)}
                            </Avatar>
                            
                            <Box sx={{ flex: 1 }}>
                              <Typography variant="subtitle2" sx={{ 
                                fontWeight: 600, 
                                fontSize: '0.75rem',
                                color: '#333'
                              }}>
                                {participation.student.name}
                              </Typography>
                              
                              {isCompleted ? (
                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                  <Typography variant="caption" sx={{ fontSize: '0.65rem', color: '#666' }}>
                                    {participation.score} von {participation.maxScore} Punkten
                                  </Typography>
                                  <Typography variant="caption" sx={{ fontSize: '0.65rem', color: '#ff9800', fontWeight: 'bold' }}>
                                    ({percentage}%)
                                  </Typography>
                                  <Typography variant="caption" sx={{ fontSize: '0.65rem', color: '#1976d2', fontWeight: 'bold' }}>
                                    Note: {gradingSystem === 'MSS' ? percentageToMSSPoints(percentage) : percentageToGrade(percentage)}
                                    {gradingSystem === 'MSS' ? ' Punkte' : ''}
                                  </Typography>
                                  <LinearProgress 
                                    variant="determinate" 
                                    value={percentage} 
                                    sx={{ 
                                      width: 60, 
                                      height: 4, 
                                      borderRadius: 2,
                                      backgroundColor: 'rgba(0,0,0,0.1)',
                                      '& .MuiLinearProgress-bar': {
                                        background: `linear-gradient(90deg, ${percentage >= 80 ? '#4caf50' : percentage >= 60 ? '#ff9800' : '#f44336'} 0%, ${percentage >= 80 ? '#45a049' : percentage >= 60 ? '#f57c00' : '#d32f2f'} 100%)`,
                                        borderRadius: 2
                                      }
                                    }} 
                                  />
                                </Box>
                              ) : (
                                <Typography variant="caption" color="text.secondary" sx={{ fontSize: '0.65rem' }}>
                                  Noch nicht abgeschlossen
                                </Typography>
                              )}
                            </Box>
                          </Box>
                          
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
                        <Chip
                          size="small"
                              label={isCompleted ? 'Abgeschlossen' : 'Aktiv'}
                              color={isCompleted ? 'success' : 'warning'}
                              icon={isCompleted ? <CheckIcon /> : <TimerIcon />}
                              sx={{ 
                                fontWeight: 600,
                                fontSize: '0.6rem',
                                height: 20
                              }}
                            />
                            
                            {isCompleted && (
                          <>
                            <Tooltip title="Auswertung anzeigen">
                              <IconButton
                                size="small"
                                color="primary"
                                onClick={() => handleViewResults(participation.id, participation.student.name)}
                                disabled={loading}
                                sx={{ 
                                      width: 24, 
                                      height: 24,
                                      bgcolor: 'primary.main',
                                      color: 'white',
                                  '&:hover': {
                                        bgcolor: 'primary.dark',
                                    transform: 'scale(1.05)',
                                        transition: 'all 0.2s ease'
                                  }
                                }}
                              >
                                    <ViewIcon sx={{ fontSize: 14 }} />
                              </IconButton>
                            </Tooltip>
                                
                            <Tooltip title="Teilnahme zurücksetzen">
                              <IconButton
                                size="small"
                                color="warning"
                                onClick={() => handleResetParticipation(participation.id, participation.student.name)}
                                disabled={loading}
                                sx={{ 
                                      width: 24, 
                                      height: 24,
                                      bgcolor: 'warning.main',
                                      color: 'white',
                                  '&:hover': {
                                        bgcolor: 'warning.dark',
                                    transform: 'scale(1.05)',
                                        transition: 'all 0.2s ease'
                                  }
                                }}
                              >
                                    <ResetIcon sx={{ fontSize: 14 }} />
                              </IconButton>
                            </Tooltip>
                          </>
                        )}
                      </Box>
                    </ListItem>
                      </Paper>
                    );
                  })}
                </List>
              </Box>
            )}

            <Typography variant="caption" color="text.secondary" sx={{ mt: 2, fontStyle: 'italic', textAlign: 'center', fontSize: '0.65rem' }}>
              Die Session läuft endlos. Schüler können das Quiz nur einmal bearbeiten.
            </Typography>
          </CardContent>
        </Card>
      )}

      {/* Results Modal */}
      {showResultsModal && selectedParticipationId && selectedStudentName && (
        <QuizResultsModal
          open={showResultsModal}
          onClose={() => {
            setShowResultsModal(false);
            setSelectedParticipationId(null);
            setSelectedStudentName(null);
          }}
          results={null}
        />
      )}

      {/* Statistics Modal */}
      {showStatisticsModal && selectedParticipationId && (
        <QuizStatisticsModal
          open={showStatisticsModal}
          onClose={() => {
            setShowStatisticsModal(false);
            setSelectedParticipationId(null);
            setSelectedStudentName(null);
          }}
          statistics={null}
        />
      )}
    </Box>
  );
}; 